def create_one_mapping_per_service(apps, schema_editor):
    """Every existing Service gets exactly one ServiceProviderMapping,
    copied from its own provider/provider_service_id/cost_rate_per_1000.
    This is what keeps introducing multi-provider routing a no-op for
    production today: resolve_best_mapping() has nothing to choose
    between until a second mapping is deliberately added later."""
    Service = apps.get_model("catalog", "Service")
    ServiceProviderMapping = apps.get_model("catalog", "ServiceProviderMapping")

    mappings = [
        ServiceProviderMapping(
            service=service,
            provider_id=service.provider_id,
            provider_service_id=service.provider_service_id,
            cost_rate_per_1000=service.cost_rate_per_1000,
            priority=0,
            is_active=True,
        )
        for service in Service.objects.all()
    ]
    ServiceProviderMapping.objects.bulk_create(mappings)


